contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 supply, uint256 value) public {
        c = new C(supply, "t", "t");
        require(supply >= value);
        uint256 balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 tsBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.burn(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert((reverted && c.balanceOf(address(this)) == balBefore && c.totalSupply() == tsBefore)
            || (!reverted && c.balanceOf(address(this)) == balBefore - value && c.totalSupply() == tsBefore - value));
    }
    receive() external payable {}
}

